"""Synthesis for the population model: layered random shapes, each layer one population with an orientation state.

The grammar (anatomix's recipe generalised):

* a **background** as anatomix makes it: a random label map (smoothed-noise blobs), a random intensity per label;
* ``K`` **layers**, each a population generated by one process: a smooth random orientation field, a shape class --
  ``line`` (extrusions along the field: fibres), ``sheet`` (discs in the plane perpendicular to the field: membranes,
  walls, laminae), ``blob`` (extrusions as short as their radius: cells, nuclei, grains) -- a radius and a length
  distribution, a density, a region, and a contrast (dark, bright, or occluding, which gives anatomix's regions as the
  occluding-blob case). Shapes follow their field, so they bend and fan;
* each layer is rendered on its own and the layers are composited, so every layer's labels are complete under the others.

The **orientation state** of a layer at a voxel is a shape tensor, not a direction: ``d dᵀ`` for a line, ``(I - n nᵀ) / 2``
for a sheet, ``I / 3`` for a blob, with a concentration ``kappa`` from the shape's aspect ratio. On the sphere it is the
Bingham/Watson function of that tensor: a lobe for a fibre, a ring for a sheet, flat for a blob -- one space for every
shape. Labels per voxel: occupancy per layer (0-1), the layer's direction and concentration, its class, its identity.

:func:`sample` draws one clean sample; :func:`nuisance` applies the acquisition and contrast nuisances (intensity remap,
polarity, gamma, bias field, elastic warp with the orientation vectors transformed by the warp's Jacobian, PSF, Gaussian
and Poisson and speckle noise, rings, streaks, resolution loss, quantisation); :func:`target` builds the lattice target
(the occupancy-weighted mixture of the layers' Bingham functions on the hemisphere grid, window-averaged).
"""
from __future__ import annotations

import math
from dataclasses import dataclass, field

import torch
import torch.nn.functional as Fn

from ..filters import gaussian


# ---------------------------------------------------------------------------------------------------------------
# random fields
# ---------------------------------------------------------------------------------------------------------------

def smooth_noise(shape, sigma: float, g: torch.Generator, device) -> torch.Tensor:
    x = torch.randn(shape, device=device, generator=g)
    x = gaussian(x, sigma, truncate=2.5) if sigma > 0 else x
    return x / x.std().clamp_min(1e-6)


def direction_field(shape, sigma: float, g: torch.Generator, device) -> torch.Tensor:
    """A smooth random unit-vector field ``(3, Z, Y, X)`` (z, y, x); ``sigma`` sets how far it stays coherent."""
    v = torch.stack([smooth_noise(shape, sigma, g, device) for _ in range(3)])
    return v / v.norm(dim=0, keepdim=True).clamp_min(1e-6)


def region_mask(shape, sigma: float, frac: float, g: torch.Generator, device) -> torch.Tensor:
    """A random region covering about ``frac`` of the block (a smoothed-noise threshold), or the whole block."""
    if frac >= 1.0:
        return torch.ones(shape, dtype=torch.bool, device=device)
    n = smooth_noise(shape, sigma, g, device)
    return n >= torch.quantile(n.flatten()[:: max(1, n.numel() // 200_000)], 1 - frac)


def label_map(shape, n_labels: int, sigma: float, g: torch.Generator, device) -> torch.Tensor:
    """anatomix's random label map: the argmax of ``n_labels`` smoothed noises, ``(Z, Y, X)`` long."""
    return torch.stack([smooth_noise(shape, sigma, g, device) for _ in range(n_labels)]).argmax(0)


# ---------------------------------------------------------------------------------------------------------------
# layers
# ---------------------------------------------------------------------------------------------------------------

@dataclass
class Layer:
    kind: str                      # "line" | "sheet" | "blob"
    field: torch.Tensor            # (3, Z, Y, X): the direction (line, blob) or the normal (sheet)
    radius: float                  # voxels (the shapes' Gaussian cross-section)
    length: float                  # voxels (the extrusion length; a disc's radius for sheets; ~radius for blobs)
    density: float                 # seeds per 1000 voxels of the region
    region: torch.Tensor           # (Z, Y, X) bool
    contrast: float                # grey levels added where the layer is (negative: dark shapes)
    occluding: bool = False        # the layer replaces the image where it is (anatomix's regions)
    coherence: float = 1.0         # the field's coherence, for the record
    kappa: float = 0.0             # the Bingham concentration of the shape's orientation state
    occupancy: torch.Tensor | None = None


def _step_along(pos: torch.Tensor, fld: torch.Tensor, shape) -> torch.Tensor:
    """The field at positions ``pos (n, 3)`` (nearest voxel), ``(n, 3)``."""
    idx = pos.round().long()
    for i, n in enumerate(shape):
        idx[:, i] = idx[:, i].clamp(0, n - 1)
    return fld[:, idx[:, 0], idx[:, 1], idx[:, 2]].T


def render_layer(layer: Layer, shape, g: torch.Generator, device, step: float = 0.5) -> torch.Tensor:
    """The layer's density ``(Z, Y, X)``: shapes grown from random seeds in the region, following the field, blurred
    by the radius; normalised so that a full shape reaches about 1 (the occupancy)."""
    Z, Y, X = shape
    n_seeds = max(1, int(layer.density * float(layer.region.sum()) / 1000.0))
    cand = layer.region.nonzero().float()
    seeds = cand[torch.randint(0, cand.shape[0], (n_seeds,), device=device, generator=g)] + torch.rand((n_seeds, 3), device=device, generator=g) - 0.5
    pts = [seeds]
    if layer.kind in ("line", "blob"):
        half = max(1, int(round(layer.length / 2 / step)))
        for sgn in (1.0, -1.0):
            p = seeds.clone(); d0 = None
            for _ in range(half):
                d = _step_along(p, layer.field, shape)
                if d0 is not None:                                                             # keep the sense of travel along an axial field
                    d = torch.where((d * d0).sum(1, keepdim=True) < 0, -d, d)
                d0 = d
                p = p + sgn * step * d; pts.append(p.clone())
    else:                                                                                      # sheet: a disc of radius ``length`` in the plane perpendicular to the normal
        n = _step_along(seeds, layer.field, shape)
        a = torch.where(n[:, :1].abs() < 0.9, torch.tensor([[1.0, 0, 0]], device=device).expand_as(n), torch.tensor([[0, 1.0, 0]], device=device).expand_as(n))
        e1 = torch.linalg.cross(n, a); e1 = e1 / e1.norm(dim=1, keepdim=True).clamp_min(1e-6); e2 = torch.linalg.cross(n, e1)
        m = max(4, int(round(2 * layer.length / step)))
        for i in range(m):
            for j in range(m):
                u = (i + 0.5) / m * 2 - 1; w = (j + 0.5) / m * 2 - 1
                if u * u + w * w <= 1:
                    pts.append(seeds + layer.length * (u * e1 + w * e2))
    P = torch.cat(pts); idx = P.round().long()
    ok = ((idx >= 0) & (idx < torch.tensor(shape, device=device))).all(1); idx = idx[ok]
    dens = torch.zeros(shape, device=device)
    dens.index_put_((idx[:, 0], idx[:, 1], idx[:, 2]), torch.ones(idx.shape[0], device=device), accumulate=True)
    dens = gaussian(dens, max(layer.radius, 0.5), truncate=3.0)
    ref = float(dens.max()) if layer.kind != "line" else max(float(torch.quantile(dens[dens > 0].flatten()[:: max(1, int((dens > 0).sum()) // 100_000)], 0.95)), 1e-6) if bool((dens > 0).any()) else 1.0
    return (dens / max(ref, 1e-6)).clamp(0, 1)


def random_layer(shape, g: torch.Generator, device, kind: str | None = None, scale: float = 1.0) -> Layer:
    """A random population. ``scale`` multiplies every length (voxel size in the trained range)."""
    u = lambda a, b: float(a + (b - a) * torch.rand(1, generator=g, device=device))
    lu = lambda a, b: float(math.exp(u(math.log(a), math.log(b))))
    kind = kind or ("line", "sheet", "blob")[int(torch.randint(0, 3, (1,), generator=g, device=device))]
    coh = lu(6, 40) * scale                                                                     # the field's coherence length (voxels): straight to winding
    fld = direction_field(shape, coh, g, device)
    radius = lu(0.6, 3.0) * scale
    if kind == "line":
        length, density = lu(20, 120) * scale, lu(0.3, 4.0) / scale ** 2
    elif kind == "sheet":
        length, density = lu(6, 30) * scale, lu(0.02, 0.3) / scale ** 2
    else:
        length, density = radius * lu(0.5, 2.5), lu(0.2, 3.0) / scale ** 3
    region = region_mask(shape, lu(8, 40) * scale, u(0.3, 1.0) if u(0, 1) < 0.7 else 1.0, g, device)
    contrast = u(25, 140) * (1 if u(0, 1) < 0.5 else -1)
    occluding = u(0, 1) < 0.2
    aspect = length / (2 * radius)
    kappa = {"line": min(2 * aspect ** 2, 60.0), "sheet": min(2 * aspect ** 2, 60.0), "blob": max(0.0, 2 * (aspect - 1) ** 2)}[kind]
    return Layer(kind, fld, radius, length, density, region, contrast, occluding, coh, min(kappa, 60.0))


# ---------------------------------------------------------------------------------------------------------------
# a sample
# ---------------------------------------------------------------------------------------------------------------

@dataclass
class Sample:
    image: torch.Tensor            # (Z, Y, X) float, grey levels 0-255 (clean)
    layers: list                   # Layer, each with .occupancy (Z, Y, X)
    background: torch.Tensor       # (Z, Y, X) the background before the layers
    labels: torch.Tensor           # (Z, Y, X) the background's label map


def sample(shape=(128, 128, 128), k_layers: int | None = None, seed: int = 0, device="cuda", scale: float = 1.0) -> Sample:
    g = torch.Generator(device=device).manual_seed(seed)
    u = lambda a, b: float(a + (b - a) * torch.rand(1, generator=g, device=device))
    nl = int(torch.randint(3, 9, (1,), generator=g, device=device))
    lab = label_map(shape, nl, u(6, 25) * scale, g, device)
    inten = 40 + 170 * torch.rand(nl, device=device, generator=g)
    bg = inten[lab] + 6 * smooth_noise(shape, 2.0 * scale, g, device)                            # a little texture inside regions
    img = bg.clone()
    K = k_layers if k_layers is not None else int(torch.randint(1, 5, (1,), generator=g, device=device))
    layers = []
    for _ in range(K):
        L = random_layer(shape, g, device, scale=scale); occ = render_layer(L, shape, g, device)
        L.occupancy = occ
        if L.occluding:
            img = torch.where(occ > 0.5, torch.full_like(img, u(30, 225)), img)
        else:
            img = img + L.contrast * occ
        layers.append(L)
    return Sample(img.clamp(0, 255), layers, bg, lab)


# ---------------------------------------------------------------------------------------------------------------
# nuisances (anatomix's, plus the CT ones)
# ---------------------------------------------------------------------------------------------------------------

def _warp_grid(disp: torch.Tensor):
    """``disp (3, Z, Y, X)`` voxel displacements -> a grid_sample grid ``(1, Z, Y, X, 3)`` in (x, y, z) order."""
    _, Z, Y, X = disp.shape
    base = torch.stack(torch.meshgrid(*(torch.arange(n, device=disp.device, dtype=torch.float32) for n in (Z, Y, X)), indexing="ij"))
    p = base + disp
    scale = torch.tensor([2.0 / max(Z - 1, 1), 2.0 / max(Y - 1, 1), 2.0 / max(X - 1, 1)], device=disp.device).view(3, 1, 1, 1)
    return (p * scale - 1.0).flip(0).movedim(0, -1)[None]


def _resample(vol: torch.Tensor, grid: torch.Tensor, mode="bilinear") -> torch.Tensor:
    v = vol[None, None] if vol.dim() == 3 else vol[None]
    out = Fn.grid_sample(v, grid, mode=mode, padding_mode="border", align_corners=True)
    return out[0, 0] if vol.dim() == 3 else out[0]


def nuisance(s: Sample, seed: int = 0, device="cuda", strength: float = 1.0) -> dict:
    """One draw of the nuisances on a clean sample. Returns the image ``(Z, Y, X)`` uint8-range float, the warped
    occupancies ``(K, Z, Y, X)``, the warped and Jacobian-rotated fields ``(K, 3, Z, Y, X)``, and the draw's record."""
    g = torch.Generator(device=device).manual_seed(seed + 7919)
    u = lambda a, b: float(a + (b - a) * torch.rand(1, generator=g, device=device))
    lu = lambda a, b: float(math.exp(u(math.log(a), math.log(b))))
    img = s.image.clone(); Z, Y, X = img.shape; rec = {}
    occ = torch.stack([L.occupancy for L in s.layers]); fld = torch.stack([L.field for L in s.layers])
    # elastic warp: a smooth displacement; labels follow; direction vectors by the Jacobian
    if u(0, 1) < 0.8 * strength:
        amp = u(0, 6) * strength; sig = lu(8, 30)
        disp = torch.stack([smooth_noise((Z, Y, X), sig, g, device) * amp for _ in range(3)])
        grid = _warp_grid(disp)
        img = _resample(img, grid); occ = _resample(occ, grid)
        J = torch.stack([torch.stack(torch.gradient(disp[i], dim=(0, 1, 2)), 0) for i in range(3)])      # (3, 3, Z, Y, X): d disp_i / d x_j
        J = J + torch.eye(3, device=device).view(3, 3, 1, 1, 1)
        fw = _resample(fld.reshape(-1, Z, Y, X), grid).reshape(fld.shape)
        # the warped image is W(x) = I(phi(x)), phi = x + disp, J = D phi: a tangent t (lines, blobs) at phi(x) is J^{-1} t at
        # x; a normal n (sheets) is J^T n (gradients transform covariantly)
        Jm = J.permute(2, 3, 4, 0, 1); Ji = torch.linalg.inv(Jm + 1e-3 * torch.eye(3, device=device)).permute(3, 4, 0, 1, 2)
        Jt = J.permute(1, 0, 2, 3, 4)
        out = []
        for k, L in enumerate(s.layers):
            M = Jt if L.kind == "sheet" else Ji
            v = torch.einsum("ijzyx,jzyx->izyx", M, fw[k]); out.append(v / v.norm(dim=0, keepdim=True).clamp_min(1e-6))
        fld = torch.stack(out); rec["warp"] = (round(amp, 2), round(sig, 1))
    # intensity: polarity, a random monotone remap (gamma + a piecewise bend), a bias field
    if u(0, 1) < 0.5:
        img = 255 - img; rec["inverted"] = True
    gam = lu(0.5, 2.0); img = 255 * (img / 255).clamp(0, 1) ** gam; rec["gamma"] = round(gam, 2)
    if u(0, 1) < 0.7:
        a, b = u(0.2, 0.8), u(0.2, 0.8); x = img / 255; img = 255 * torch.where(x < a, b * x / a, b + (1 - b) * (x - a) / (1 - a)); rec["bend"] = (round(a, 2), round(b, 2))
    if u(0, 1) < 0.8:
        bias = 1 + u(0.1, 0.5) * strength * smooth_noise((Z, Y, X), lu(20, 60), g, device); img = img * bias; rec["bias"] = True
    # resolution and PSF: a random, possibly anisotropic Gaussian blur; a down-up resampling
    sig = [lu(0.3, 2.0) for _ in range(3)]
    if u(0, 1) < 0.5:
        sig = [sig[0] * lu(1.5, 4.0), sig[1], sig[2]]                                           # a PSF longer along one axis (the slice axis)
    img = gaussian(img, tuple(sig), truncate=3.0); rec["psf"] = [round(x, 2) for x in sig]
    if u(0, 1) < 0.3:
        f = lu(1.2, 2.5); small = Fn.interpolate(img[None, None], scale_factor=1 / f, mode="trilinear", align_corners=False)
        img = Fn.interpolate(small, size=(Z, Y, X), mode="trilinear", align_corners=False)[0, 0]; rec["resolution"] = round(f, 2)
    # noise: Poisson (shot), Gaussian, speckle
    if u(0, 1) < 0.6:
        P = lu(15, 1500); img = torch.poisson((img / 255).clamp(0, 1) * P, generator=g) / P * 255; rec["poisson_photons"] = round(P)
    if u(0, 1) < 0.9:
        sd = u(0, 30) * strength; img = img + sd * torch.randn(img.shape, device=device, generator=g); rec["gaussian_sd"] = round(sd, 1)
    if u(0, 1) < 0.3:
        img = img * (1 + u(0, 0.25) * torch.randn(img.shape, device=device, generator=g)); rec["speckle"] = True
    # CT artefacts
    if u(0, 1) < 0.35:
        from ..artefacts import rings
        img = torch.as_tensor(rings(img.round().clamp(0, 255).to(torch.uint8).cpu().numpy(), u(5, 60), seed=seed, device=device)[0], device=device).float(); rec["rings"] = True
    if u(0, 1) < 0.35:
        from ..artefacts import streaks
        img = torch.as_tensor(streaks(img.round().clamp(0, 255).to(torch.uint8).cpu().numpy(), u(10, 80), spread_deg=u(5, 90), seed=seed, device=device)[0], device=device).float(); rec["streaks"] = True
    # slice-wise intensity jitter (a slice axis)
    if u(0, 1) < 0.4:
        img = img * (1 + u(0.02, 0.12) * torch.randn(Z, device=device, generator=g)).view(Z, 1, 1); rec["slice_jitter"] = True
    img = img.round().clamp(0, 255); rec["quantised"] = True
    return {"image": img, "occupancy": occ.clamp(0, 1), "fields": fld, "record": rec}


# ---------------------------------------------------------------------------------------------------------------
# the target on the sphere
# ---------------------------------------------------------------------------------------------------------------

def bingham(grid: torch.Tensor, fld: torch.Tensor, kind: str, kappa: float) -> torch.Tensor:
    """The orientation state on the hemisphere ``grid (n, 3)`` for a field ``(3, ...)``: a Watson lobe along the field
    for lines (and blobs, with their small kappa), a girdle (ring) perpendicular to the normal for sheets; ``(n, ...)``,
    normalised to unit mean over the sphere."""
    c2 = torch.einsum("nc,c...->n...", grid, fld) ** 2
    f = torch.exp(kappa * (c2 - 1)) if kind in ("line", "blob") else torch.exp(-kappa * c2)
    return f / f.mean(0, keepdim=True).clamp_min(1e-9)


def target(s: Sample, drawn: dict, grid: torch.Tensor, step: int = 4, sigma_w: float = 10.0) -> dict:
    """The lattice target: ``odf (n, z, y, x)`` the occupancy-weighted mixture of the layers' Bingham functions,
    window-averaged (``sigma_w`` voxels) and pooled to ``step``; ``occupancy (K, z, y, x)``; ``kind`` per layer."""
    occ, fld = drawn["occupancy"], drawn["fields"]
    K = occ.shape[0]; n = grid.shape[0]
    acc = torch.zeros((n,) + tuple(occ.shape[1:]), device=occ.device)
    for k, L in enumerate(s.layers):
        acc += occ[k][None] * bingham(grid, fld[k], L.kind, L.kappa)
    pool = lambda x: Fn.avg_pool3d(gaussian(x, sigma_w, truncate=2.5)[None], step)[0]
    return {"odf": pool(acc), "occupancy": pool(occ), "kinds": [L.kind for L in s.layers], "kappas": [round(L.kappa, 1) for L in s.layers]}
